"short": "O violão Di Giorgio Bird´s Eye surge como uma ótima opção no mercado.",
"description": [
"O violão Di Giorgio Bird´s Eye surge como uma ótima opção no mercado.",
"Sua principal característica é o braço mais fino, com dimensões de braço de guitarra, o que facilita muito a vida dos que tem mãos pequenas ou enfrentam dificuldades em algumas aberturas de acordes. As cordas são realmente bem mais próximas umas das outras. Podemos verificar isso pela distância entre as duas cordas MI, que é de apenas 37 mm.",
"A sonoridade é ótima, pois a caixa acústica do Di Giorgio Bird´s Eye é um pouco maior que a dos outros violões, com profundidade de 109 mm. É o que eles chamam de mini-jumbo. O som tem muita sustentação.",
"As cordas tem boa tensão(1), dando firmeza ao músico para a execução dos acordes, num ótimo equilíbrio entre conforto e sonoridade.",
"Um dos pontos fortes desse instrumento é a captação com muitas opções de equalização, afinador e com duas saídas diferente, uma para cabos P10 e outra para cabos XLR (iguais aos cabos para microfone).",
"A madeira principal é o Maple, e o tampo de Spruce Canadense, que ganham boa projeção com a grande caixa acústica do Di Giorgio Bird´s Eye.",
"O corpo tem o corte (cutway) para que possamos alcançar as notas mais agudas com facilidade.",
"Essa foi uma solução muito interessante encontrada pela Di Giorgio para atender ao público, pois o Bird´s Eye agrega as vantagens de um violão de náilon (por que suas cordas são de náilon), ao mesmo tempo que oferece um corpo muito parecido com os violões feitos para cordas de aço. Essa fusão gerou um violão com uma sonoridade única. É um violão que tem a “pegada” de um violão de aço mas com o conforto do náilon.",
"Largura da pestana (distância entre as duas cordas MI): 37 mm",
"Comprimento escala (distância entre pestana e rastilho): 645mm"
],
